import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { PageTabs } from '@/components/shared/PageTabs'
import { PageViews } from '@/components/shared/PageViews'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import { InventoryHub } from '@/components/inventory/InventoryHub'
import { InkRegistryTable } from '@/components/reach/InkRegistryTable'
import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'

export const metadata: Metadata = {
  title: 'Inventory — InkOS',
}

const INVENTORY_TABS: PageTab[] = [
  {
    key: 'stock',
    label: 'Stock',
    href: '/inventory?tab=stock',
  },
  {
    key: 'ink-registry',
    label: 'Ink Registry',
    href: '/inventory?tab=ink-registry',
    hidden: (role) => role !== 'owner' && role !== 'admin',
  },
]

const VALID_KEYS = new Set(INVENTORY_TABS.map((t) => t.key))

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function InventoryPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  // S18 fix — plan gating removed per product direction. Sidebar still shows a
  // STUDIO pill on this item as a visual hint; page is accessible on all plans.
  // We still read the plan so PageTabs can show tab-level plan pills. Re-introduce
  // feature restrictions in S19 via in-page contextual gates.
  const supabase = await createClient()
  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  const role = auth.role as NavRole
  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_KEYS.has(rawTab) ? rawTab : 'stock'

  return (
    <PageShell>
      <PageHeader
        title="Inventory"
        description="Track consumables, manage suppliers, and monitor stock levels."
      />

      <PageViews>
        <PageTabs
          tabs={filterTabsForRole(INVENTORY_TABS, role)}
          activeKey={activeKey}
          currentPlan={plan}
          currentRole={role}
        />
      </PageViews>

      <div role="tabpanel" id={`tabpanel-${activeKey}`} className="flex flex-col flex-1 min-h-0">
        <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 rounded-xl min-h-[200px]" />}>
          {activeKey === 'stock' && <InventoryHub />}

          {activeKey === 'ink-registry' && (
            <div className="max-w-6xl space-y-6">
              <InkRegistryTable />
            </div>
          )}
        </Suspense>
      </div>
    </PageShell>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { checkFeatureRpc } from '@/lib/billing/feature-gate'
import { LocationsGrid } from '@/components/locations/LocationsGrid'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import type { LocationStatus, MultiLocationOverview } from '@/lib/supabase/types'

export const metadata: Metadata = {
  title: 'Locations — InkOS',
}

export default async function LocationsPage() {
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) redirect('/onboarding')

  const studioId = member.studio_id
  const canManage = ['owner', 'admin'].includes(member.role)
  const hasMultiLocation = await checkFeatureRpc(supabase, studioId, 'multi_location')

  if (!hasMultiLocation) {
    return (
      <PageShell>
        <PageHeader
          title="Locations"
          description="Studio locations and chairs"
        />
        <div className="max-w-2xl">
          <UpgradeGatePageBlock
            requiredPlan="pro"
            feature="Multi-location management"
            description="Manage multiple studio locations, assign artists, override services, and view rollup analytics across all sites."
          />
        </div>
      </PageShell>
    )
  }

  const { data: rawLocations } = await supabase
    .from('locations')
    .select(`
      id, name, status, city, state, timezone,
      address, cover_image_url, sort_order, manager_id
    `)
    .eq('studio_id', studioId)
    .order('sort_order', { ascending: true })
    .order('created_at', { ascending: true })

  const locList = rawLocations ?? []

  // Enrich each location with counts and manager name
  const locations = await Promise.all(
    locList.map(async (loc, idx) => {
      const [artistRes, bookingRes, managerRes] = await Promise.all([
        supabase
          .from('location_assignments')
          .select('id', { count: 'exact', head: true })
          .eq('location_id', loc.id),
        supabase
          .from('appointments')
          .select('id', { count: 'exact', head: true })
          .eq('location_id', loc.id)
          .gte(
            'start_at',
            new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString(),
          ),
        loc.manager_id
          ? supabase
              .from('profiles')
              .select('first_name, last_name')
              .eq('id', loc.manager_id)
              .single()
          : Promise.resolve({ data: null }),
      ])

      const managerData = managerRes.data as { first_name: string; last_name: string } | null

      return {
        id: loc.id,
        name: loc.name,
        address: loc.address ?? null,
        city: loc.city ?? null,
        state: loc.state ?? null,
        status: loc.status as LocationStatus,
        is_primary: idx === 0, // first location by sort_order is primary
        manager: managerData
          ? { full_name: `${managerData.first_name} ${managerData.last_name}` }
          : null,
        artist_count: artistRes.count ?? 0,
        bookings_this_month: bookingRes.count ?? 0,
        opening_hours_summary: null, // compute if needed
      }
    }),
  )

  // Fetch overview RPC (only when >1 location)
  let overview: MultiLocationOverview | null = null
  if (locations.length > 1) {
    const { data: overviewData } = await supabase.rpc('get_multi_location_overview', {
      p_studio_id: studioId,
    })
    if (overviewData) {
      overview = overviewData as unknown as MultiLocationOverview
    }
  }

  return (
    <PageShell>
      <PageHeader
        title="Locations"
        description="Studio locations and chairs"
      />
      <LocationsGrid
        locations={locations}
        overview={overview}
        canManage={canManage}
      />
    </PageShell>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import {
  listConversations,
  getConversation,
  getConversationMessages,
  getClientBookingsSummary,
} from '@/lib/messaging/queries'
import { markConversationRead } from '@/lib/messaging/mutations'
import { MessagesShell } from '@/components/messages/MessagesShell'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'

export const metadata: Metadata = {
  title: 'Messages — InkOS',
}

export default async function MessagesPage() {
  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { conversations } = await listConversations(studioId, {
    limit: 50,
    archived: false,
  })

  // Auto-select the most recent conversation (desktop convenience;
  // mobile MessagesShell shows the list only and navigates on tap).
  const firstConversation = conversations[0] ?? null
  const activeConversationId = firstConversation?.id ?? null

  let activeConversation = null
  let activeMessages: Awaited<ReturnType<typeof getConversationMessages>> = []
  let recentBookings: Awaited<ReturnType<typeof getClientBookingsSummary>> = []

  if (activeConversationId) {
    activeConversation = await getConversation(studioId, activeConversationId)

    if (activeConversation) {
      const [msgs, bookings] = await Promise.all([
        getConversationMessages(studioId, activeConversationId, { limit: 50 }),
        activeConversation.client
          ? getClientBookingsSummary(studioId, activeConversation.client.id, 3)
          : Promise.resolve([]),
      ])
      activeMessages = msgs
      recentBookings = bookings

      if (activeConversation.unread_count > 0) {
        await markConversationRead(studioId, activeConversationId)
      }
    }
  }

  return (
    <PageShell fullHeight>
      <div className="px-4 py-4 sm:px-6 lg:px-8 shrink-0">
        <PageHeader
          title="Messages"
          description="SMS and email conversations with clients"
        />
      </div>
      <div className="flex-1 min-h-0">
        <MessagesShell
          conversations={conversations}
          activeConversation={activeConversation}
          activeMessages={activeMessages}
          recentBookings={recentBookings}
          studioId={studioId}
          activeConversationId={activeConversationId ?? undefined}
        />
      </div>
    </PageShell>
  )
}

