'use client'

import { useState } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { useRouter, useSearchParams } from 'next/navigation'
import { AppointmentsTable, type BulkAppointmentItem } from '@/components/appointments/AppointmentsTable'
import { AppointmentCreateDrawer } from '@/components/appointments/AppointmentCreateDrawer'
import { BulkRescheduleSheet } from '@/components/appointments/BulkRescheduleSheet'
import { BulkCancelSheet } from '@/components/appointments/BulkCancelSheet'
import { AppointmentDetailDrawer } from '@/components/appointments/AppointmentDetailDrawer'
import { PullToRefresh } from '@/components/shared/PullToRefresh'

interface AppointmentsPageClientProps {
  /**
   * When true, forces the appointments table to filter to today's date.
   * Used by the "Today" tab on the /appointments tab host page.
   */
  forceToday?: boolean
}

export function AppointmentsPageClient({ forceToday }: AppointmentsPageClientProps) {
  const queryClient = useQueryClient()
  const router = useRouter()
  const [drawerOpen, setDrawerOpen] = useState(false)
  const searchParams = useSearchParams()

  // M2: wire ?date=today param — also overridden by forceToday prop (S13 "Today" tab)
  const dateParam = searchParams.get('date')
  const initialDateFilter: 'today' | undefined =
    forceToday === true || dateParam === 'today' ? 'today' : undefined

  // Bulk action state
  const [bulkRescheduleOpen, setBulkRescheduleOpen] = useState(false)
  const [bulkCancelOpen, setBulkCancelOpen] = useState(false)
  const [bulkAppointments, setBulkAppointments] = useState<BulkAppointmentItem[]>([])

  // Detail drawer state
  const [detailOpen, setDetailOpen] = useState(false)
  const [detailAppointmentId, setDetailAppointmentId] = useState<string | undefined>(undefined)

  return (
    <PullToRefresh
      onRefresh={async () => {
        router.refresh()
        await queryClient.invalidateQueries({ queryKey: ['bookings'] })
      }}
      className="flex flex-col flex-1 overflow-hidden h-full"
    >
      <AppointmentsTable
        onNewAppointment={() => setDrawerOpen(true)}
        initialDateFilter={initialDateFilter}
        onBulkReschedule={(appointments) => {
          setBulkAppointments(appointments)
          setBulkRescheduleOpen(true)
        }}
        onBulkCancel={(appointments) => {
          setBulkAppointments(appointments)
          setBulkCancelOpen(true)
        }}
        onRowClick={(id) => {
          setDetailAppointmentId(id)
          setDetailOpen(true)
        }}
      />

      <AppointmentCreateDrawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        editingId={null}
        onSuccess={() => {
          setDrawerOpen(false)
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }}
      />

      <BulkRescheduleSheet
        open={bulkRescheduleOpen}
        onOpenChange={setBulkRescheduleOpen}
        appointments={bulkAppointments}
        onSuccess={() => {
          setBulkAppointments([])
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }}
      />

      <BulkCancelSheet
        open={bulkCancelOpen}
        onOpenChange={setBulkCancelOpen}
        appointments={bulkAppointments}
        onSuccess={() => {
          setBulkAppointments([])
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }}
      />

      <AppointmentDetailDrawer
        open={detailOpen}
        onOpenChange={setDetailOpen}
        appointmentId={detailAppointmentId}
      />

)}

{/* Grid header */}
<div className="flex items-center justify-between">
  <div>
    <Typography variant="h2">
      {locations.length > 0 ? `${locations.length} location${locations.length !== 1 ? 's' : ''}` : 'Locations'}
    </Typography>
  </div>
  {canManage && (
    <Button size="sm" render={<Link href="/locations/new" />}>

  return (
    <div className="flex flex-col items-center justify-center h-full text-center px-8">
      <div className="h-14 w-14 rounded-2xl bg-primary/10 flex items-center justify-center mb-4">
        <MessageSquare className="h-7 w-7 text-primary" aria-hidden />
      </div>
      <h2 className="font-semibold text-foreground mb-1">
        {hasConversations ? 'Select a conversation' : 'No messages yet'}
      </h2>
      <p className="text-sm text-muted-foreground max-w-xs">
        {hasConversations
          ? 'Choose a conversation from the left to view messages.'
          : 'When clients message you via SMS or email, their conversations will appear here.'}
      </p>
    </div>
  )
}

'use client'

import Link from 'next/link'
import type { ReactNode } from 'react'
import { MoreHorizontal } from 'lucide-react'
import { PageShell } from './PageShell'
import { PageHeader } from './PageHeader'
import { PageTabs, type PageTab } from './PageTabs'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

/**
 * S24 — Polaris-inspired `<Page>` composite.
 *
 * One entry point for every top-level authenticated route. Composes the
 * existing PageShell + PageHeader + PageTabs primitives with a typed
 * action API so every page shares the same rhythm:
 *
 *   Title + subtitle + metadata     [secondary actions] [primary action]
 *   Optional tab row (underline style)
 *   Children (content — the page owns its own rhythm below)
 *
 * Use `<Page>` for every standard route. Reach for the underlying primitives
 * directly only for exceptional layouts (dashboard hero, onboarding chrome).
 */

export interface PageAction {
  /** Button label. Required. */
  label: string
  /** Optional click handler for state-based actions (open drawer, etc.). */
  onClick?: () => void
  /** Optional href for nav-based actions. Mutually exclusive with onClick. */
  href?: string
  /**
   * Optional leading icon — pass a pre-rendered React element (e.g. `<Plus className="h-3.5 w-3.5" />`).
   * A component reference cannot be passed: Server Components can only serialize
   * plain React elements across the RSC boundary, not constructors.
   */
  icon?: ReactNode
  /** Loading state — disables the button and swaps the label for a spinner. */
  loading?: boolean
  /** Disabled state. */
  disabled?: boolean
  /** Use the destructive variant (red) instead of default/secondary. */
  destructive?: boolean
}

export interface PageProps {
  /** Page title — rendered in Instrument Serif per brand. */
  title: string
  /** Short description under the title. */
  subtitle?: string
  /**
   * Chips/badges rendered inline to the right of the title (status badges,
   * LIVE pills, plan badges). Kept small so they don't break the H1 rhythm.
   */
  titleMetadata?: ReactNode
  /** Back link rendered above the title (usually on detail pages). */
  backAction?: { href: string; label?: string }
  /** Primary call-to-action — Onyx fill, top-right. Max one per page. */
  primaryAction?: PageAction
  /**
   * Secondary actions — outline buttons left of the primary action. First two
   * render inline; the rest collapse into an overflow "..." dropdown so the
   * header never exceeds a single row.
   */
  secondaryActions?: PageAction[]
  /** Tab row below the header. */
  tabs?: PageTab[]
  /** Active tab key — required when `tabs` is provided. */
  activeTab?: string
  /** Current plan — required for tab plan-gating. Defaults to 'solo'. */
  plan?: PlanTier
  /** Current role — required for tab role-filtering. Defaults to 'owner'. */
  role?: NavRole
  /** Pass-through to PageShell for calendar / messages style full-height layouts. */
  fullHeight?: boolean
  /**
   * Narrow the content width for forms / settings pages. `720` → 720px,
   * `960` → 960px, `false` / undefined → default 1440px cap.
   */
  narrowWidth?: 720 | 960 | false
  /** Extra classes applied to the outer PageShell. */
  className?: string
  /** Page content. */
  children: ReactNode
}

function ActionButton({
  action,
  primary = false,
}: {
  action: PageAction
  primary?: boolean
}) {
  const variant = action.destructive
    ? 'destructive'
    : primary
    ? 'default'
    : 'outline'

  const content = (
    <>
      {action.icon}
      {action.label}
    </>
  )

  if (action.href) {
    return (
      <Button
        variant={variant}
        size="sm"
        loading={action.loading ?? false}
        disabled={action.disabled ?? false}
        render={<Link href={action.href} />}
      >
        {content}
      </Button>
    )
  }

  return (
    <Button
      variant={variant}
      size="sm"
      loading={action.loading ?? false}
      disabled={action.disabled ?? false}
      onClick={action.onClick}
    >
      {content}
    </Button>
  )
}

function SecondaryActionsRow({ actions }: { actions: PageAction[] }) {
  if (actions.length === 0) return null

  // First two render inline; the rest collapse into an overflow menu so the
  // header stays single-row even on pages with many secondary tools.
  const inline = actions.slice(0, 2)
  const overflow = actions.slice(2)

  return (
    <>
      {inline.map((action) => (
        <ActionButton key={action.label} action={action} />
      ))}
      {overflow.length > 0 && (
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button variant="outline" size="sm" className="h-9 w-9 p-0" aria-label="More actions">
                <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
              </Button>
            }
          />
          <DropdownMenuContent align="end">
            {overflow.map((action) => {
              if (action.href) {
                return (
                  <DropdownMenuItem
                    key={action.label}
                    className="gap-2 text-xs"
                    disabled={action.disabled ?? false}
                    render={<Link href={action.href} />}
                  >
                    {action.icon}
                    {action.label}
                  </DropdownMenuItem>
                )
              }
              return (
                <DropdownMenuItem
                  key={action.label}
                  className={action.destructive ? 'gap-2 text-xs text-destructive focus:text-destructive' : 'gap-2 text-xs'}
                  disabled={action.disabled ?? false}
                  onClick={action.onClick}
                >
                  {action.icon}
                  {action.label}
                </DropdownMenuItem>
              )
            })}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </>
  )
}

export function Page({
  title,
  subtitle,
  titleMetadata,
  backAction,
  primaryAction,
  secondaryActions = [],
  tabs,
  activeTab,
  plan = 'solo',
  role = 'owner',
  fullHeight = false,
  narrowWidth,
  className,
  children,
}: PageProps) {
  const maxWidth = narrowWidth === false ? false : narrowWidth ?? 1440
  const hasActions = primaryAction != null || secondaryActions.length > 0

  // Build the header `actions` slot from the typed action arrays.
  const actionsNode = hasActions ? (
    <>
      <SecondaryActionsRow actions={secondaryActions} />
      {primaryAction && <ActionButton action={primaryAction} primary />}
    </>
  ) : undefined

  // Build the title node with optional metadata chips to the right.
  const titleNode = titleMetadata ? (
    <div className="flex items-center gap-3 min-w-0">
      <span className="min-w-0 truncate">{title}</span>
      <span className="flex items-center gap-1.5 shrink-0">{titleMetadata}</span>
    </div>
  ) : (
    title
  )

  return (
    <PageShell
      fullHeight={fullHeight}
      maxWidth={maxWidth}
      {...(className ? { className } : {})}
    >
      {/* When titleMetadata is present we need a ReactNode instead of string; the
          PageHeader today expects a string title, so render chips INSIDE the
          existing description slot as a row above for that edge case. Simpler
          path: always pass `title` as string and stamp the metadata via an
          absolutely-positioned slot. For now we pass the string title. */}
      <PageHeader
        title={typeof titleNode === 'string' ? titleNode : title}
        {...(subtitle ? { description: subtitle } : {})}
        {...(actionsNode ? { actions: actionsNode } : {})}
        {...(backAction ? { backHref: backAction.href } : {})}
      />

      {/* Metadata chips rendered just under the title — preserves the existing
          PageHeader contract while giving us Polaris-style titleMetadata. */}
      {titleMetadata && (
        <div className="-mt-4 flex items-center gap-1.5">{titleMetadata}</div>
      )}

      {tabs && tabs.length > 0 && activeTab && (
        <PageTabs tabs={tabs} activeKey={activeTab} currentPlan={plan} currentRole={role} />
      )}

      {children}
    </PageShell>
  )
}

